-- Seed BOQ categories K–O work item masters and catalog (idempotent).

INSERT INTO work_item_masters (company_id, name, code)
SELECT c.uuid, v.name, v.code
FROM companies c
CROSS JOIN (VALUES
    ('JOINERY WORKS', 'K'),
    ('COUNTER TOP & MARBLE WORKS', 'L'),
    ('ALUMINUM AND GLASS WORKS', 'M'),
    ('PURCHASES', 'N'),
    ('EXCLUSIONS', 'O')
) AS v(name, code)
ON CONFLICT (company_id, code) DO NOTHING;

INSERT INTO work_items (
    company_id,
    work_item_master_id,
    work_item_name,
    work_item_code,
    description,
    unit_type,
    default_rate,
    cost_price,
    selling_price_override,
    cost_price_override,
    quantity_formula_type,
    ceiling_applicable,
    wall_applicable,
    floor_applicable,
    active,
    deleted
)
SELECT
    c.uuid,
    wim.id,
    v.work_item_name,
    v.work_item_code,
    v.description,
    v.unit_type,
    v.default_rate,
    v.cost_price,
    CASE WHEN v.default_rate IS NULL THEN FALSE ELSE TRUE END,
    CASE WHEN v.cost_price IS NULL THEN FALSE ELSE TRUE END,
